/**
 * Demo dataset: a fictional water treatment and utility plant.
 *
 * "Northfork Utility District" and "Basalt Ridge Plant" are invented. Every
 * person, asset, reading and work order here is fictional. This file is the
 * single source of truth for both the in-memory demo store and
 * `supabase/seed.sql` (generated by `pnpm seed:sql`).
 *
 * Dates are stored as "days ago" offsets so the demo never looks stale.
 */
import { seedId } from "./ids";
import type {
  AreaCode,
  Asset,
  Craft,
  Criticality,
  InventoryRow,
  Organization,
  Part,
  Priority,
  Profile,
  Site,
  WoPartStatus,
  WoStage,
  WoStatus,
  WoType,
} from "@/types/domain";

export const ORG: Organization = { id: seedId("org", 1), name: "Northfork Utility District" };

export const SITE: Site = {
  id: seedId("site", 1),
  org_id: ORG.id,
  code: "BRP",
  name: "Basalt Ridge Plant",
  timezone: "America/Los_Angeles",
};

const AREA_DEFS: [string, string][] = [
  ["INT", "Raw Water Intake"],
  ["HSP", "High-Service Pump Station"],
  ["FIL", "Filtration"],
  ["CHM", "Chemical Feed"],
  ["BLR", "Boiler House"],
  ["CTW", "Cooling Tower"],
  ["ELE", "Electrical & Substation"],
  ["AIR", "Compressed Air"],
];

export const AREAS: AreaCode[] = AREA_DEFS.map(([code, name], i) => ({
  id: seedId("area", i + 1),
  site_id: SITE.id,
  code,
  name,
}));

const areaId = (code: string) => {
  const area = AREAS.find((a) => a.code === code);
  if (!area) throw new Error(`Unknown area ${code}`);
  return area.id;
};

