export const ASSETS: Asset[] = ASSET_DEFS.map((d, i) => ({
  id: seedId("asset", i + 1),
  site_id: SITE.id,
  area_id: areaId(d.floc.split("-")[1]),
  parent_id: null,
  floc: d.floc,
  name: d.name,
  asset_class: d.cls,
  criticality: d.crit,
  manufacturer: d.mfr ?? null,
  model: d.model ?? null,
  serial_number: `SN-${(48210 + i * 37).toString()}`,
  install_date: d.installYear ? `${d.installYear}-06-01` : null,
  status: d.status ?? "running",
  notes: d.notes ?? null,
}));
// Resolve parent FLOCs after ids exist.
ASSET_DEFS.forEach((d, i) => {
  if (d.parent) ASSETS[i].parent_id = assetId(d.parent);
});

export function assetId(floc: string) {
  const a = ASSETS.find((x) => x.floc === floc);
  if (!a) throw new Error(`Unknown asset ${floc}`);
  return a.id;
}

