export const PARTS: Part[] = PART_DEFS.map((d, i) => ({
  id: seedId("part", i + 1),
  org_id: ORG.id,
  part_number: d.pn,
  description: d.desc,
  manufacturer: d.mfr ?? null,
  mfr_part_number: d.mpn ?? null,
  category: d.cat,
  unit: d.unit ?? "ea",
  unit_cost: d.cost,
}));

export const INVENTORY: InventoryRow[] = PART_DEFS.map((d, i) => ({
  id: seedId("inventory", i + 1),
  site_id: SITE.id,
  part_id: PARTS[i].id,
  bin: d.bin,
  on_hand: d.onHand,
  reserved: 0,
  min_qty: d.min,
  max_qty: d.max,
}));

export function partId(pn: string) {
  const p = PARTS.find((x) => x.part_number === pn);
  if (!p) throw new Error(`Unknown part ${pn}`);
  return p.id;
}

